 receipt_raw=(OUT/'receipt.json').read_bytes();receipt=json.loads(receipt_raw);assert receipt['passed'];source=next(s for s in json.loads((ROOT/'data/manifests/northeast.json').read_text())if s['id']==receipt['source_id']);integration=json.loads((ROOT/'docs/evidence/source-audit-northeast/se-ifa-adapter-integration.json').read_text());source_binding_sha=sha(json.dumps(source,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode());assert source_binding_sha==integration['source_binding_sha256_after']=='68e0721bffd9a246c05aefe534c004e8e0291ab510e0d76c4bb60ea03c7c3d95';assert source['uncoded_items_path']==receipt['candidate_path'];assert sha((ROOT/source['uncoded_items_path']).read_bytes())==receipt['candidate_sha256'];assert source['sha256']==receipt['source_sha256']==sha((ROOT/source['local_path']).read_bytes());assert source['adapter_authority']=={'coded_learning_ranges':[[p,p]for p in receipt['page_scope']]};assert all(source.get(k)==v for k,v in integration['protected_fields_unchanged'].items());assert source['structured_subset']['peer_sha256']==sha(receipt_raw)
 doc=pymupdf.open(ROOT/source['local_path']);E={'source_id':source['id'],'sha256':source['sha256'],'pages':[{'page':p,'text':doc[p-1].get_text('text',sort=True)}for p in receipt['page_scope']]};errors=[];loaded=ingest.source_uncoded_items([source],{source['id']:E},errors);assert not errors,errors;assert len(loaded)==305;before={i['id']:i for i in loaded};final=ingest.attach_hierarchy(ingest.finalize_items(loaded,[source]),[source]);assert len(final)==len({i['id']for i in final})==305;assert all(all(i.get(k)==before[i['id']].get(k)for k in ['text','code','positions','evidence'])for i in final);schema=validators(ROOT)['Learning'];schema_errors=[{'id':i['id'],'message':e.message}for i in final for e in schema.iter_errors(i)];assert not schema_errors,schema_errors
 result={'actor_type':'automated','actor_id':'codex-independent-se-ifa-peer','generated_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'passed':True,'actual_Source_binding_sha256':source_binding_sha,'source_artifact_sha256':source['sha256'],'actual_sidecar_path':source['uncoded_items_path'],'sidecar_sha256':receipt['candidate_sha256'],'accepted_peer_receipt_sha256':sha(receipt_raw),'authority_exact40unit_page_ranges':True,'protected_Source_fields_equal_integration_receipt':True,'generic_page_sections_not_suppressed':True,'loader_finalizer_hierarchy_schema_records':305,'all305text_code_positions_evidence_preserved':True,'current_cache_read_or_refreshed':False,'cache_config_freshness_or_publication_verified':False,'whole_Source_UF_ready_human_pedagogy_claimed':False,'MF_core_cache_database_publication_modified':False};(OUT/'actual-binding.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');print(sha((OUT/'actual-binding.json').read_bytes()))
